//! The string kernels against Spark 4.2 on seeded random inputs
//! (`tests/fixtures/spark-4.2.0/string-differential.json`, generated by
//! `tests/scripts/gen_string_goldens.py`): every recorded case, run in bulk
//! as columns.
#![forbid(unsafe_code)]

use std::collections::BTreeSet;

use arrow_array::types::Int32Type;
use arrow_array::{Array, Int32Array, ListArray, StringArray, cast::AsArray};
use krishiv_kernels::string::{
    MatchKind, PadSide, StrOperand, TrimSide, char_length, concat, like, lower, match_str, pad,
    replace, split_literal, substring, trim, upper,
};
use krishiv_kernels::{KernelCtx, Operand};
use serde_json::Value;

type R = Result<(), Box<dyn std::error::Error>>;
type S<'a> = StrOperand<'a, i32>;

struct Group<'a> {
    name: String,
    cases: Vec<&'a Value>,
}

impl Group<'_> {
    fn str_col(&self, i: usize) -> StringArray {
        self.cases.iter().map(|c| c["args"][i].as_str()).collect()
    }

    fn int_col(&self, i: usize) -> Int32Array {
        self.cases
            .iter()
            .map(|c| c["args"][i].as_i64().and_then(|v| i32::try_from(v).ok()))
            .collect()
    }

    /// Compares the kernel's rows with Spark's.
    fn check(&self, got: &[Value], failures: &mut Vec<String>) {
        assert_eq!(got.len(), self.cases.len(), "{}", self.name);
        for (c, g) in self.cases.iter().zip(got) {
            if *g != c["out"] {
                failures.push(format!(
                    "{}{}: got {g}, Spark {}",
                    self.name, c["args"], c["out"]
                ));
            }
        }
    }
}

fn strings(a: &StringArray) -> Vec<Value> {
    a.iter()
        .map(|s| s.map_or(Value::Null, Value::from))
        .collect()
}

fn bools(a: &arrow_array::BooleanArray) -> Vec<Value> {
    a.iter()
        .map(|s| s.map_or(Value::Null, Value::from))
        .collect()
}

fn lists(a: &ListArray) -> Vec<Value> {
    (0..a.len())
        .map(|i| {
            if a.is_null(i) {
                Value::Null
            } else {
                Value::from(
                    a.value(i)
                        .as_string::<i32>()
                        .iter()
                        .map(|s| s.unwrap_or_default().to_owned())
                        .collect::<Vec<_>>(),
                )
            }
        })
        .collect()
}

#[test]
fn kernels_match_spark_on_random_inputs() -> R {
    let path = krishiv_testkit::tests_dir().join("fixtures/spark-4.2.0/string-differential.json");
    let fixture: Value = serde_json::from_str(&std::fs::read_to_string(path)?)?;
    let all = fixture["cases"].as_array().ok_or("cases")?;
    let names: BTreeSet<&str> = all.iter().filter_map(|c| c["fn"].as_str()).collect();
    let ctx = KernelCtx::new();
    let mut failures = Vec::new();
    for name in &names {
        let cases: Vec<&Value> = all.iter().filter(|c| c["fn"] == *name).collect();
        let g = Group {
            name: (*name).to_owned(),
            cases,
        };
        let a = g.str_col(0);
        let arg = |i: usize| -> StringArray { g.str_col(i) };
        match *name {
            "upper" => g.check(&strings(&upper(&a, &ctx)?), &mut failures),
            "lower" => g.check(&strings(&lower(&a, &ctx)?), &mut failures),
            "char_length" => {
                let n = char_length(&a);
                let got: Vec<Value> = n
                    .iter()
                    .map(|v| v.map_or(Value::Null, Value::from))
                    .collect();
                g.check(&got, &mut failures);
            }
            "substring2" | "substring3" => {
                let pos = g.int_col(1);
                let len = (*name == "substring3").then(|| g.int_col(2));
                let out = substring(
                    S::Array(&a),
                    Operand::<Int32Type>::Array(&pos),
                    len.as_ref().map(Operand::Array),
                )?;
                g.check(&strings(&out), &mut failures);
            }
            "lpad2" | "lpad3" | "rpad2" | "rpad3" => {
                let side = if name.starts_with('l') {
                    PadSide::Left
                } else {
                    PadSide::Right
                };
                let (len, fill) = (g.int_col(1), (name.ends_with('3')).then(|| arg(2)));
                let out = pad(
                    side,
                    S::Array(&a),
                    Operand::Array(&len),
                    fill.as_ref().map(StrOperand::Array),
                )?;
                g.check(&strings(&out), &mut failures);
            }
            "trim1" => g.check(
                &strings(&trim(TrimSide::Both, S::Array(&a), None)?),
                &mut failures,
            ),
            "btrim2" => {
                let c = arg(1);
                let out = trim(TrimSide::Both, S::Array(&a), Some(S::Array(&c)))?;
                g.check(&strings(&out), &mut failures);
            }
            "trim2" | "ltrim2" | "rtrim2" => {
                // `trim(chars, str)`.
                let (chars, s) = (arg(0), arg(1));
                let side = match *name {
                    "ltrim2" => TrimSide::Leading,
                    "rtrim2" => TrimSide::Trailing,
                    _ => TrimSide::Both,
                };
                let out = trim(side, S::Array(&s), Some(S::Array(&chars)))?;
                g.check(&strings(&out), &mut failures);
            }
            "replace3" => {
                let (b, c) = (arg(1), arg(2));
                let out = replace(S::Array(&a), S::Array(&b), S::Array(&c))?;
                g.check(&strings(&out), &mut failures);
            }
            "like2" => {
                let p = arg(1);
                let out = like(S::Array(&a), S::Array(&p), '\\')?;
                g.check(&bools(&out), &mut failures);
            }
            "like3" => {
                // One kernel call per escape character.
                for esc in ["\\", "$", "!"] {
                    let sub = Group {
                        name: format!("like3[{esc}]"),
                        cases: g
                            .cases
                            .iter()
                            .copied()
                            .filter(|c| c["args"][2] == esc)
                            .collect(),
                    };
                    let (s, p) = (sub.str_col(0), sub.str_col(1));
                    let escape = esc.chars().next().ok_or("escape")?;
                    let out = like(S::Array(&s), S::Array(&p), escape)?;
                    sub.check(&bools(&out), &mut failures);
                }
            }
            "startswith" | "endswith" | "contains" => {
                let kind = match *name {
                    "startswith" => MatchKind::StartsWith,
                    "endswith" => MatchKind::EndsWith,
                    _ => MatchKind::Contains,
                };
                let b = arg(1);
                let out = match_str(kind, S::Array(&a), S::Array(&b))?;
                g.check(&bools(&out), &mut failures);
            }
            "concat3" => {
                let (b, c) = (arg(1), arg(2));
                let out = concat(&[S::Array(&a), S::Array(&b), S::Array(&c)])?;
                g.check(&strings(&out), &mut failures);
            }
            "split3" => {
                // One kernel call per delimiter.
                let delimiters: BTreeSet<&str> = g
                    .cases
                    .iter()
                    .filter_map(|c| c["args"][1].as_str())
                    .collect();
                for d in delimiters {
                    let sub = Group {
                        name: format!("split3[{d}]"),
                        cases: g
                            .cases
                            .iter()
                            .copied()
                            .filter(|c| c["args"][1] == d)
                            .collect(),
                    };
                    let (s, limit) = (sub.str_col(0), sub.int_col(2));
                    let literal = krishiv_kernels::string::literal_delimiter(d)
                        .ok_or("delimiter is a regular expression")?;
                    let out = split_literal(S::Array(&s), &literal, Operand::Array(&limit))?;
                    sub.check(&lists(&out), &mut failures);
                }
            }
            other => return Err(format!("no kernel for fixture function {other}").into()),
        }
    }
    assert!(
        failures.is_empty(),
        "{} differences, first: {:#?}",
        failures.len(),
        &failures[..failures.len().min(25)]
    );
    Ok(())
}
